/**
 * 기업 계약 동의 (PRD R-208, WO §9.4, R-218).
 *
 * - The "구인 서비스 이용약관" draft lives in `content/terms/employer/{version}/{locale}.md`
 *   ([전문가 검토 필요], non-Korean files carry the Korean original — SC-08). The current version
 *   is the highest version folder. A PDF of each file is generated by `scripts/build-terms-pdf.ts`
 *   into `public/docs/` (`termsPdfPath`).
 * - Signing needs the terms box only. The 체류 업무 위임 동의 (`visaMandateAgreed`) is a separate,
 *   optional box: not ticking it never blocks the contract (WO §9.4 "묶어 강제하지 않는다").
 * - On signing, in one transaction: `Company.contractSignedAt` / `contractVersion` /
 *   `visaMandateAgreed`, and Consent rows (`EMPLOYER_TERMS`, plus `EMPLOYER_VISA_MANDATE` when
 *   ticked) for the signing account, with the version and locale.
 * - The candidate list also needs staff verification (`verified`, R-218); signing alone shows the
 *   summary only.
 */
import { existsSync, readdirSync, readFileSync } from "node:fs";
import path from "node:path";

import { type Locale, defaultLocale, locales } from "@/i18n/locales";
import { db } from "@/lib/db";
import { consentIpHash } from "@/lib/seeker/consent";

import type { EmployerActor } from "./session";

const TERMS_DIR = path.join(process.cwd(), "content", "terms", "employer");

/** contractVersion written when staff record a contract signed outside the app (R-218). */
export const STAFF_RECORDED_CONTRACT = "STAFF_RECORDED";

export const EMPLOYER_TERMS_CONSENT = "EMPLOYER_TERMS";
export const EMPLOYER_VISA_MANDATE_CONSENT = "EMPLOYER_VISA_MANDATE";

function versionNumber(v: string): number {
  const m = /^v([0-9]+)$/.exec(v);
  return m ? Number(m[1]) : -1;
}

/** Current terms version folder (e.g. "v1"). */
export function currentTermsVersion(dir: string = TERMS_DIR): string {
  const versions = existsSync(dir) ? readdirSync(dir).filter((v) => versionNumber(v) >= 0) : [];
  if (versions.length === 0) throw new Error("employer terms body missing");
  return versions.sort((a, b) => versionNumber(b) - versionNumber(a))[0];
}

function termsLocale(locale: string): Locale {
  return (locales as readonly string[]).includes(locale) ? (locale as Locale) : defaultLocale;
}

export type TermsDocument = { version: string; locale: Locale; body: string };

/** Terms body of the current version in `locale` (Korean when the translation is missing). */
export function getTermsDocument(locale: string): TermsDocument {
  const version = currentTermsVersion();
  const l = termsLocale(locale);
  const file = path.join(TERMS_DIR, version, `${l}.md`);
  const useLocale = existsSync(file) ? l : defaultLocale;
  const body = readFileSync(path.join(TERMS_DIR, version, `${useLocale}.md`), "utf8");
  return { version, locale: useLocale, body };
}

/** Public path of the generated PDF (`scripts/build-terms-pdf.ts`). */
export function termsPdfPath(version: string, locale: string): string {
  return `/docs/employer-terms-${version}-${termsLocale(locale)}.pdf`;
}

export type ContractStatus = {
  signedAt: Date | null;
  version: string | null;
  visaMandateAgreed: boolean;
  verified: boolean;
};

export async function contractStatusOf(
  companyId: string,
  client: typeof db = db,
): Promise<ContractStatus | null> {
  const c = await client.company.findUnique({
    where: { id: companyId },
    select: {
      contractSignedAt: true,
      contractVersion: true,
      visaMandateAgreed: true,
      verified: true,
    },
  });
  if (!c) return null;
  return {
    signedAt: c.contractSignedAt,
    version: c.contractVersion,
    visaMandateAgreed: c.visaMandateAgreed,
    verified: c.verified,
  };
}

export type SignContractResult =
  | { ok: true; version: string; visaMandateAgreed: boolean }
  | { ok: false; code: "TERMS_REQUIRED" | "ALREADY_SIGNED" | "NO_COMPANY" };

export async function signEmployerContract(
  args: {
    actor: EmployerActor;
    termsAgreed: boolean;
    visaMandate: boolean;
    locale: Locale;
    ip: string | null;
    now?: Date;
  },
  client: typeof db = db,
): Promise<SignContractResult> {
  if (!args.termsAgreed) return { ok: false, code: "TERMS_REQUIRED" };
  const now = args.now ?? new Date();
  const version = currentTermsVersion();
  const ipHash = consentIpHash(args.ip);
  return client.$transaction(async (tx) => {
    // Only an unsigned company is updated (a concurrent second submit changes nothing).
    const updated = await tx.company.updateMany({
      where: { id: args.actor.companyId, contractSignedAt: null },
      data: {
        contractSignedAt: now,
        contractVersion: version,
        visaMandateAgreed: args.visaMandate,
      },
    });
    if (updated.count === 0) {
      const exists = await tx.company.count({ where: { id: args.actor.companyId } });
      return {
        ok: false as const,
        code: exists ? ("ALREADY_SIGNED" as const) : ("NO_COMPANY" as const),
      };
    }
    const base = { userId: args.actor.id, version, locale: args.locale, agreedAt: now, ipHash };
    await tx.consent.create({ data: { ...base, type: EMPLOYER_TERMS_CONSENT } });
    if (args.visaMandate) {
      await tx.consent.create({ data: { ...base, type: EMPLOYER_VISA_MANDATE_CONSENT } });
    }
    return { ok: true as const, version, visaMandateAgreed: args.visaMandate };
  });
}
